import { Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { childAttributes, html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Menu from "../../ui/base-ui-menu";

type Action =
  | "Add to Library"
  | "Add to Playlist"
  | "Play Next"
  | "Play Last"
  | "Favorite"
  | "Share";

const ActionMenu = Menu.create<Action>();
const actions: readonly Action[] = [
  "Add to Library",
  "Add to Playlist",
  "Play Next",
  "Play Last",
  "Favorite",
  "Share",
];

const caretDownIcon = (): Html => {
  const h = html<Message>();

  return h.svg(
    [
      h.Attribute("width", "16"),
      h.Attribute("height", "16"),
      h.Attribute("viewBox", "0 0 16 16"),
      h.Attribute("fill", "currentColor"),
      h.AriaHidden(true),
      h.Class("block"),
    ],
    [h.path([h.Attribute("d", "M12 6H4l4 4.5z")], [])]
  );
};

// MODEL

export const Model = S.Struct({
  menu: Menu.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotMenuMessage = m("GotMenuMessage", {
  message: Menu.Message,
});

export const Message = S.Union([GotMenuMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const [menu, menuCommands] = Menu.init({ id: "menu-basic" });

  return [
    { menu },
    Command.mapMessages(menuCommands, (message) => GotMenuMessage({ message })),
  ];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotMenuMessage: ({ message }) => {
        const [menu, menuCommands] = ActionMenu.update(model.menu, message);

        return [
          evo(model, { menu: () => menu }),
          Command.mapMessages(menuCommands, (message) =>
            GotMenuMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: model.menu.id,
    model: model.menu,
    view: ActionMenu.view,
    viewInputs: {
      anchor: Menu.baseUiMenuDefaultAnchor,
      items: actions,
      itemToConfig: (item) => ({
        className:
          actions.indexOf(item) === 2 || actions.indexOf(item) === 4
            ? `${Menu.baseUiMenuItemClassName} border-t border-gray-200`
            : Menu.baseUiMenuItemClassName,
        content: h.span([], [item]),
      }),
      buttonContent: h.span(
        [h.Class("inline-flex items-center gap-2")],
        [h.span([], ["Song"]), caretDownIcon()]
      ),
      buttonAttributes: childAttributes([
        h.Class(Menu.baseUiMenuTriggerClassName),
      ]),
      itemsAttributes: childAttributes([
        h.Class(Menu.baseUiMenuPopupClassName),
      ]),
      backdropAttributes: childAttributes([
        h.DataAttribute("testid", "menu-backdrop"),
        h.Class(Menu.baseUiMenuBackdropClassName),
      ]),
      attributes: childAttributes([h.Class(Menu.baseUiMenuRootClassName)]),
    },
    toParentMessage: (message) => GotMenuMessage({ message }),
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Menu from "../../ui/menu";
import { GotMenuMessage, init, update, view } from "./main";

const [initialModel] = init();

const AnchorMenu = Menu.AnchorMenu({
  buttonId: "menu-basic-button",
  anchor: Menu.defaultAnchor,
});
const FocusItems = Menu.FocusItems({ id: "menu-basic" });
const FocusButton = Menu.FocusButton({ id: "menu-basic" });

const resolveMenuMounts = () =>
  Scene.Mount.resolveAll(
    [
      Menu.PortalMenuBackdrop,
      Menu.CompletedPortalMenuBackdrop(),
      (message) => GotMenuMessage({ message }),
    ],
    [
      AnchorMenu,
      Menu.CompletedAnchorMenu(),
      (message) => GotMenuMessage({ message }),
    ]
  );

describe("menu-basic example", () => {
  test("opens items and closes through the backdrop", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Song" })).toExist(),
      Scene.expect(Scene.text("Bold")).not.toExist(),
      Scene.expect(Scene.text("Add to Library")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Song" })),
      Scene.Command.expectHas(FocusItems),
      Scene.Command.resolve(FocusItems, Menu.CompletedFocusItems(), (message) =>
        GotMenuMessage({ message })
      ),
      resolveMenuMounts(),
      Scene.expect(Scene.text("Add to Library")).toExist(),
      Scene.expect(Scene.text("Add to Playlist")).toExist(),
      Scene.expect(Scene.text("Play Next")).toExist(),
      Scene.expect(Scene.text("Play Last")).toExist(),
      Scene.expect(Scene.text("Favorite")).toExist(),
      Scene.expect(Scene.text("Share")).toExist(),
      Scene.click(Scene.testId("menu-backdrop")),
      Scene.Command.expectHas(FocusButton),
      Scene.Command.resolve(
        FocusButton,
        Menu.CompletedFocusButton(),
        (message) => GotMenuMessage({ message })
      ),
      Scene.Mount.expectEnded(Menu.PortalMenuBackdrop, AnchorMenu),
      Scene.expect(Scene.text("Add to Library")).not.toExist()
    );
  });
});
